Set-Location -LiteralPath $PSScriptRoot
$msg = 'twilio: credentials belong to the organization, numbers belong to people. _resolve_twilio_creds only used an advisor number when that advisor row also carried a SID and auth token, so one A2P brand with a number per FSA required copying the org auth token onto every advisor row. New ladder: advisor own account (legacy) -> advisor assigned number on org credentials -> optional org shared number -> refuse. No platform fallback anywhere. The org shared number is now optional. Adds per-advisor number assignment with a platform-wide uniqueness check so inbound reply routing stays unambiguous, and declares the seven A2P columns the model never had - dlc_router guarded every write with hasattr, so every SID Twilio returned was silently discarded.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
